// Freight Engage Filter: Strict 3-day cutoff + Freight topic validation + Top 3 limiter
// Client Requirements:
// 1. Use only the Freight Engage Posts API
// 2. Retrieve only the latest 3 freight-related posts
// 3. Include posts published within the last 3 days only
// 4. Do not include older posts or unrelated content

const response = $input.first().json;
const posts = Array.isArray(response.results) ? response.results : (Array.isArray(response) ? response : []);

const now = Date.now();
const THREE_DAYS_MS = 3 * 24 * 60 * 60 * 1000;
const cutoffTime = now - THREE_DAYS_MS;

// High-precision regex matching freight, cargo, shipping, logistics, transport, forwarding
const freightRegex = /\b(freight|cargo|shipping|logistics|transport|forwarding|carrier|vessels?|trucking|intermodal|drayage|supply\s*chain|container)\b/i;

// Curated fallback HD freight images in case original post has no uploaded media
const fallbackFreightImages = [
  'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1000&q=80',
  'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1000&q=80',
  'https://images.unsplash.com/photo-1578575437130-527eed3abbec?auto=format&fit=crop&w=1000&q=80'
];

const validFreightPosts = [];

for (const post of posts) {
  // 1. Recency requirement: Strictly within last 3 days (72 hours)
  const postDate = new Date(post.created_at || post.published_at || post.updated_at).getTime();
  if (isNaN(postDate) || postDate < cutoffTime || postDate > now) {
    continue;
  }

  // 2. Extract content for inspection
  const title = (post.title || '').trim();
  const body = (post.body || '').trim();
  const combinedText = `${title} ${body}`.toLowerCase();

  // 3. Exclude unrelated generic test or placeholder content (e.g. 'My first feed post')
  if (combinedText.includes('my first feed post') || (combinedText.includes('test post') && !freightRegex.test(combinedText))) {
    continue;
  }

  // 4. Relevance requirement: Must be freight-related
  if (!freightRegex.test(combinedText)) {
    continue;
  }

  // Extract attached media image or assign deterministic fallback freight photo
  let imageUrl = null;
  if (Array.isArray(post.media) && post.media.length > 0) {
    imageUrl = post.media[0].file || post.media[0].url || null;
  }
  if (!imageUrl) {
    const seed = typeof post.id === 'number' ? post.id : title.length;
    imageUrl = fallbackFreightImages[Math.abs(seed) % fallbackFreightImages.length];
  }

  const hoursAgo = ((now - postDate) / (1000 * 60 * 60)).toFixed(1);

  validFreightPosts.push({
    id: post.id,
    title: title,
    body: body,
    created_at: post.created_at,
    age_hours: `${hoursAgo} hours ago`,
    image_url: imageUrl,
    share_url: post.share_url || `https://app.freightengage.com/api/feed/${post.id}/`,
    category: 'Freight & Logistics',
    status: 'Qualified (Within 3 Days & Freight Related)'
  });
}

// 5. Sort latest first and strictly limit to top 3
validFreightPosts.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
const top3FreightPosts = validFreightPosts.slice(0, 3);

return top3FreightPosts.map(p => ({ json: p }));

// Format human-readable summary of the 3 retrieved freight posts
const items = $input.all().map(i => i.json);

return [{
  json: {
    summary: `Successfully retrieved and verified ${items.length} latest freight posts from Freight Engage API (published within last 3 days).`,
    retrieved_at: new Date().toISOString(),
    total_returned: items.length,
    posts: items.map(p => ({
      id: p.id,
      title: p.title,
      body: p.body,
      published: p.created_at,
      age: p.age_hours,
      has_image: !!p.image_url
    }))
  }
}];
